old = '''<section class="section" id="productos"><div class="secHead"><h2>Productos destacados</h2><button class="linkbtn" onclick="loadProducts()">Ver todos los productos&nbsp; ›</button></div><div class="products" id="productGrid"></div></section>
<section class="routeBanner"><div class="rbTitle"><div class="truck">🚚</div><div><b>Entrega profesional<br>con <span>RutaFV</span></b><small>Tu compra, entregada en cualquier punto de Fuerteventura</small></div></div><div class="rbFeatures"><div class="rbFeature"><span class="fi">⌖</span><div><b>Cobertura insular</b><small>Servicio de entrega en todos los municipios de Fuerteventura.</small></div></div><div class="rbFeature"><span class="fi">✓</span><div><b>Transporte profesional</b><small>Mercancía gestionada con seguimiento y entrega coordinada.</small></div></div><div class="rbFeature"><span class="fi">↗</span><div><b>Seguimiento del pedido</b><small>Consulta el estado del reparto desde la preparación hasta la entrega.</small></div></div></div><div class="van"></div></section>
<div class="benefits"><div class="benefit"><span>✓</span><div><b>Calidad profesional</b><small>Productos seleccionados</small></div></div><div class="benefit"><span>♙</span><div><b>Atención al cliente</b><small>Estamos para ayudarte</small></div></div><div class="benefit"><span>▣</span><div><b>Pagos seguros</b><small>Compra con total confianza</small></div></div><div class="benefit"><span>↻</span><div><b>Gestión sencilla</b><small>Seguimiento de pedidos</small></div></div></div>'''

new = '''<section class="promoRow" aria-label="Promociones FVMarket"><article class="promoCard promoReform"><div><h3>Especial Reformas</h3><p>Todo para tu baño y cocina</p><button class="promoBtn" onclick="filterCategory('Reformas')">Ver productos&nbsp; →</button></div></article><article class="promoCard promoOffer"><div><h3>Ofertas destacadas</h3><p>Calidad al mejor precio</p><button class="promoBtn" onclick="filterOffers()">Ver ofertas&nbsp; →</button></div></article></section>
<section class="bottomShowcase" id="productos"><div class="bottomHead"><h2>Productos destacados</h2><button class="linkbtn" onclick="loadProducts()">Ver todos&nbsp; →</button></div><div class="bottomGrid"><div class="bottomProducts"><div class="products" id="productGrid"></div></div><aside class="shipCalc"><div class="shipCalcTitle"><span class="shipCalcIcon">🚚</span><div><h3>Calcula tu envío con <span>RutaFV</span></h3><p>Introduce tu dirección para consultar el coste de transporte de los productos que tienes en el carrito.</p></div></div><div class="field"><label>Dirección de entrega</label><input id="quickShipAddress" placeholder="Introduce tu dirección en Fuerteventura"></div><div class="shipCalc2"><div class="field"><label>Municipio</label><input id="quickShipCity" placeholder="Ej. Gran Tarajal"></div><div class="field"><label>CP</label><input id="quickShipPostal" inputmode="numeric" placeholder="35620"></div></div><button class="shipCalcBtn" onclick="quickRutaFVQuote()">Calcular envío&nbsp; →</button><div id="quickShipMsg" class="shipCalcMsg">Añade productos al carrito e inicia sesión para calcular el transporte.</div><div class="shipCalcFoot"><span>⌖ Entrega en toda la isla</span><span>▣ Transporte seguro</span></div></aside></div></section>'''

if old not in s:
    raise SystemExit('No se encontró el bloque inferior esperado')
s=s.replace(old,new,1)

hook = "function filterOffers(){loadProducts().then(()=>{products=products.filter(p=>p.onOffer||p.hasDiscount);renderProducts();document.getElementById('productos').scrollIntoView({behavior:'smooth'})})}"
if hook not in s:
    raise SystemExit('No se encontró filterOffers')
extra = hook + r'''
async function quickRutaFVQuote(){const msg=document.getElementById('quickShipMsg');const address=(document.getElementById('quickShipAddress')?.value||'').trim();const city=(document.getElementById('quickShipCity')?.value||'').trim();const postal=(document.getElementById('quickShipPostal')?.value||'').trim();if(!session){msg.className='shipCalcMsg';msg.textContent='Inicia sesión para calcular el transporte con RutaFV.';openAccount();return}if(!cart.length){msg.className='shipCalcMsg';msg.textContent='Añade al menos un producto al carrito para calcular el envío.';return}if(!address||!city||!postal){msg.className='shipCalcMsg';msg.textContent='Completa dirección, municipio y código postal.';return}msg.className='shipCalcMsg';msg.textContent='Calculando transporte con RutaFV…';try{const q=await api('/api/rutafv/quote',{method:'POST',body:JSON.stringify({items:cart,address:[address,city,postal].filter(Boolean).join(', '),city,postalCode:postal,phone:''})});const amount=Number(q.amount??q.total??0);msg.className='shipCalcMsg ok';msg.textContent='Transporte RutaFV: '+eur(amount)+' · se añadirá al pago del pedido.'}catch(e){msg.className='shipCalcMsg';msg.textContent='No se pudo calcular el envío: '+e.message}}
'''
s=s.replace(hook,extra,1)

p.write_text(s,encoding='utf-8')
print('OK formato inferior aplicado')
